import * as React from "react";
import { announce } from "@/lib/announce";

export interface UsePullToRefreshOptions {
  /**
   * Refresh action run when the user pulls past the threshold and releases.
   * The spinner stays visible until the returned promise settles.
   */
  onRefresh: () => void | Promise<void>;
  /**
   * Ref to the scroll container to watch. Omit (or pass a ref whose `current`
   * is null) for apps that scroll the document/window rather than an inner
   * element -- the gesture then reads `window.scrollY`.
   */
  scrollRef?: React.RefObject<HTMLElement | null>;
  /** Disable the gesture entirely (e.g. signed out, nothing to refresh). */
  disabled?: boolean;
  /** Pull distance (px, after resistance) past which release triggers a refresh. */
  threshold?: number;
  /** Announced to screen readers when a refresh starts (an i18n string). */
  refreshingLabel?: string;
  /** Announced to screen readers when a refresh finishes (an i18n string). */
  refreshedLabel?: string;
}

export interface UsePullToRefreshResult {
  /** Current visual pull distance in px (after resistance); 0 when idle. */
  pullDistance: number;
  /** True while `onRefresh` is in flight. */
  isRefreshing: boolean;
}

const DEFAULT_THRESHOLD = 64;
const RESISTANCE = 0.5;
// Match useSwipeNavigation's axis-lock slop so a pull and a horizontal
// tab-swipe are decided the same way and never fight each other.
const AXIS_SLOP = 8;
const MAX_PULL = 120;

/**
 * Pull-to-refresh for touch devices. A downward drag that STARTS at the top of
 * the scroll container reveals a refresh affordance; releasing past `threshold`
 * runs `onRefresh`. Opt-in and gesture-driven:
 *
 * - Coexists with the iOS overscroll fix (`overscroll-behavior: none`): that
 *   only suppresses the visual bounce, not touch events, and this hook owns the
 *   gesture by calling `preventDefault` on a non-passive `touchmove` listener.
 * - Coexists with `useSwipeNavigation`: it locks to one axis after `AXIS_SLOP`
 *   and only acts on a downward VERTICAL drag, so horizontal tab-swipes are
 *   untouched. It never engages mid-page (only when scrolled to the very top).
 * - Touch-only (desktop keeps its explicit Sync action). Motion is handled by
 *   the global `prefers-reduced-motion` stylesheet, so no JS gating is needed.
 *
 * Pair with `PullToRefreshIndicator` for the spinner. Pass i18n strings for the
 * screen-reader announcements; the indicator itself is visual-only.
 */
export function usePullToRefresh({
  onRefresh,
  scrollRef,
  disabled = false,
  threshold = DEFAULT_THRESHOLD,
  refreshingLabel,
  refreshedLabel,
}: UsePullToRefreshOptions): UsePullToRefreshResult {
  const [pullDistance, setPullDistance] = React.useState(0);
  const [isRefreshing, setIsRefreshing] = React.useState(false);

  // Refs so the listeners (registered once per effect run) always read fresh
  // values without re-registering on every render.
  const onRefreshRef = React.useRef(onRefresh);
  onRefreshRef.current = onRefresh;
  const pullDistanceRef = React.useRef(0);
  pullDistanceRef.current = pullDistance;
  const isRefreshingRef = React.useRef(false);

  React.useEffect(() => {
    if (disabled) return;

    const el = scrollRef?.current ?? null;
    const target: HTMLElement | Window = el ?? window;
    const scrollTopOf = () =>
      el ? el.scrollTop : window.scrollY || document.documentElement.scrollTop;

    let startY: number | null = null;
    let startX: number | null = null;
    let axis: "vertical" | "horizontal" | null = null;
    let pulling = false;

    const reset = () => {
      startY = null;
      startX = null;
      axis = null;
      pulling = false;
    };

    const onTouchStart = (e: TouchEvent) => {
      if (isRefreshingRef.current || e.touches.length !== 1) return;
      if (scrollTopOf() > 0) {
        startY = null;
        return;
      }
      startY = e.touches[0].clientY;
      startX = e.touches[0].clientX;
      axis = null;
      pulling = false;
    };

    const onTouchMove = (e: TouchEvent) => {
      if (startY === null || startX === null || isRefreshingRef.current) return;
      const dy = e.touches[0].clientY - startY;
      const dx = e.touches[0].clientX - startX;

      if (axis === null && (Math.abs(dx) > AXIS_SLOP || Math.abs(dy) > AXIS_SLOP)) {
        axis = Math.abs(dy) > Math.abs(dx) ? "vertical" : "horizontal";
      }

      // Only a downward vertical drag while pinned to the top is a pull.
      if (axis !== "vertical" || dy <= 0 || scrollTopOf() > 0) {
        if (pulling) {
          pulling = false;
          setPullDistance(0);
        }
        return;
      }

      pulling = true;
      // We own the gesture now -- stop the browser from scrolling/bouncing.
      if (e.cancelable) e.preventDefault();
      setPullDistance(Math.min(MAX_PULL, dy * RESISTANCE));
    };

    const onTouchEnd = () => {
      if (startY === null) return;
      const triggered = pulling && pullDistanceRef.current >= threshold;
      reset();
      if (!triggered || isRefreshingRef.current) {
        setPullDistance(0);
        return;
      }
      isRefreshingRef.current = true;
      setIsRefreshing(true);
      setPullDistance(threshold); // park at threshold while spinning
      if (refreshingLabel) announce(refreshingLabel);
      Promise.resolve(onRefreshRef.current())
        .catch(() => {})
        .finally(() => {
          isRefreshingRef.current = false;
          setIsRefreshing(false);
          setPullDistance(0);
          if (refreshedLabel) announce(refreshedLabel);
        });
    };

    target.addEventListener("touchstart", onTouchStart as EventListener, { passive: true });
    target.addEventListener("touchmove", onTouchMove as EventListener, { passive: false });
    target.addEventListener("touchend", onTouchEnd as EventListener);
    target.addEventListener("touchcancel", onTouchEnd as EventListener);
    return () => {
      target.removeEventListener("touchstart", onTouchStart as EventListener);
      target.removeEventListener("touchmove", onTouchMove as EventListener);
      target.removeEventListener("touchend", onTouchEnd as EventListener);
      target.removeEventListener("touchcancel", onTouchEnd as EventListener);
    };
  }, [scrollRef, disabled, threshold, refreshingLabel, refreshedLabel]);

  return { pullDistance, isRefreshing };
}
